        for width in [0, 1, 64, 512] {
            let statements = (0..width)
                .map(|i| format!("let n{i}=0;"))
                .collect::<String>();
            let source = format!("module app; @id(\"app.main\") fn main()->i64 {{{statements}0}}");
            let program =
                crate::hir::resolve(&crate::parse(&source, "linear-renewals.spx").unwrap())
                    .unwrap();
