            }
            Ok(())
        },
    )?;
    let helpers = crate::loop_calls::byte_writer::checked_bindings_with_reservation_and_work(
        program, function, physical, charge,
    )?;
    Ok(RenewalBindings {
        legacy,
        appends,
        helpers: HelperSites::Owned(helpers),
    })
}
