                    Frame::Expression(
                        function,
                        crate::hir::lexical_exit::ChildCursor::new(e),
                        false,
                        0,
                    )
                })
            }
        };
        if let Some(child) = child {
            if depth == DEPTH {
                return None;
            }
            frames[depth] = Some(child);
            depth += 1;
        } else {
            frames[current] = None;
            depth -= 1;
        }
